export function autoCorrelate(buffer, sampleRate) {
  // Perform autocorrelation to extract fundamental frequency from raw wave buffer
  const SIZE = buffer.length;
  let r = new Float32Array(SIZE);
  for (let i = 0; i < SIZE; i++) {
    for (let j = 0; j < SIZE - i; j++) {
      r[i] = r[i] + buffer[j] * buffer[j + i];
    }
  }

  // Find the peak in autocorrelation above a certain threshold
  let d = 0;
  while (r[d] > r[d + 1]) d++;

  let maxval = -1;
  let maxpos = -1;
  for (let i = d; i < SIZE; i++) {
    if (r[i] > maxval) {
      maxval = r[i];
      maxpos = i;
    }
  }

  let T0 = maxpos;

  // Verify correlation is strong enough
  if (r[T0] > 0.9 * r[0]) {
    return sampleRate / T0; // Frequency in Hz
  }
  return -1;
}

