import React, { useRef, useState } from 'react';
import * as Tone from 'tone';
import { autoCorrelate } from './pitchDetector';

export const AudioEngine = () => {
  const [isRecording, setIsRecording] = useState(false);
  const audioContextRef = useRef(null);
  const analyserRef = useRef(null);

  const startRecording = async () => {
    await Tone.start();
    audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    const source = audioContextRef.current.createMediaStreamSource(stream);

    analyserRef.current = audioContextRef.current.createAnalyser();
    analyserRef.current.fftSize = 2048;
    source.connect(analyserRef.current);

    setIsRecording(true);
    runAnalysis();
  };

  const runAnalysis = () => {
    if (!isRecording) return;
    const buffer = new Float32Array(analyserRef.current.fftSize);
    analyserRef.current.getFloatTimeDomainData(buffer);

    const frequency = autoCorrelate(buffer, audioContextRef.current.sampleRate);
    if (frequency !== -1) {
       console.log("Detected frequency:", frequency);
       // Map frequency to MIDI note and play back
    }
    requestAnimationFrame(runAnalysis);
  };

  return (
    <div className="engine-controls">
      <button onClick={startRecording}>Start Capturing Mic</button>
    </div>
  );
};
